import copy
class C:__copy__=None
c=C();c.value=3
try:print(copy.copy(c).value)
except TypeError as e:print(type(e).__name__)

import copy
class C:__deepcopy__=None
c=C();c.value=3
try:print(copy.deepcopy(c).value)
except TypeError as e:print(type(e).__name__)

